<?php session_start(); require '../config.php'; require_admin(); $counts=[]; foreach(['Pending','Under Review','Accepted','Rejected'] as $s){$q=db()->prepare("SELECT COUNT(*) FROM applications WHERE status=?");$q->execute([$s]);$counts[$s]=(int)$q->fetchColumn();} $total=array_sum($counts); $apps=db()->query("SELECT application_no,full_name,class_applied,status,created_at FROM applications ORDER BY created_at DESC LIMIT 10")->fetchAll(); $mediaCount=db()->query("SELECT COUNT(*) FROM media")->fetchColumn(); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Dashboard</title><link rel="stylesheet" href="../assets/css/style.css"></head><body class="admin-body"><header class="admin-head"><div><img src="../assets/images/school-logo.png"><strong>ME’RAJ ADMIN PORTAL</strong></div><nav><a href="dashboard.php">Dashboard</a><a href="applications.php">Applications</a><a href="media.php">Media</a><a href="logout.php">Logout</a></nav></header><main class="admin-main"><div class="container"><h1>Welcome, <?=e($_SESSION['admin_name'])?></h1><div class="stats"><div><b><?=$total?></b><span>Total Applications</span></div><div><b><?=$counts['Pending']?></b><span>Pending</span></div><div><b><?=$counts['Under Review']?></b><span>Under Review</span></div><div><b><?=$counts['Accepted']?></b><span>Accepted</span></div><div><b><?=$mediaCount?></b><span>Media Items</span></div></div><div class="card table-card"><div class="section-head"><h2>Recent Applications</h2><a class="more" href="applications.php">View all →</a></div><div class="table-wrap"><table><thead><tr><th>Application No.</th><th>Student</th><th>Class</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($apps as $a): ?><tr><td><a href="application.php?no=<?=urlencode($a['application_no'])?>"><?=e($a['application_no'])?></a></td><td><?=e($a['full_name'])?></td><td><?=e($a['class_applied'])?></td><td><span class="status status-<?=strtolower(str_replace(' ','-',$a['status']))?>"><?=e($a['status'])?></span></td><td><?=e($a['created_at'])?></td></tr><?php endforeach; ?></tbody></table></div></div></div></main></body></html>